#include <stdio.h>
#include <string.h>

static char P[100005];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    if (scanf("%100004s", P) != 1) return 0;

    int ans = 0;
    /* A raiz tem comprimento m que divide N, com m < N (>= 2 blocos).
       Testa os divisores em ordem crescente; o primeiro que funcionar
       e o de menor comprimento. Custo por divisor: O(N). */
    for (int m = 1; m < n; ++m) {
        if (n % m) continue;

        int cnt[26] = {0};
        for (int i = 0; i < m; ++i) ++cnt[P[i] - 'a'];

        int ok = 1;
        for (int s = m; s < n && ok; s += m) {
            int tmp[26];
            memcpy(tmp, cnt, sizeof tmp);
            const char *q = P + s;
            for (int i = 0; i < m; ++i) {
                int c = q[i] - 'a';
                if (--tmp[c] < 0) { ok = 0; break; }
            }
            if (ok) {
                for (int c = 0; c < 26; ++c)
                    if (tmp[c]) { ok = 0; break; }
            }
        }

        if (ok) { ans = m; break; }
    }

    if (ans) {
        fwrite(P, 1, ans, stdout);
        fputc('\n', stdout);
    } else {
        fputc('*', stdout);
        fputc('\n', stdout);
    }
    return 0;
}
